// Vendor payment list ---------------------------------------------------------------
// Keyset pagination (newest first): pass the created_at and id of the last
// row you showed as the cursor, or NULLs for the first page. Ask for
// page_limit + 1 rows; an extra row means there's a next page. Unlike
// OFFSET, a page costs the same however deep it is, and rows arriving
// meanwhile don't shift what the next page shows. Every filter is optional
// (NULL = no filter).
func (q *Queries) ListBranchPayments(ctx context.Context, arg ListBranchPaymentsParams) ([]ListBranchPaymentsRow, error) {
	rows, err := q.db.Query(ctx, listBranchPayments,
		arg.BranchID,
		arg.Statuses,
		arg.CreatedFrom,
		arg.CreatedTo,
		arg.Reference,
		arg.CursorCreatedAt,
		arg.CursorID,
		arg.PageLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListBranchPaymentsRow
	for rows.Next() {
		var i ListBranchPaymentsRow
		if err := rows.Scan(
			&i.ID,
			&i.OrderID,
			&i.Provider,
			&i.Status,
			&i.FailureCode,
			&i.Currency,
			&i.AmountAuthorised,
			&i.AmountCaptured,
			&i.AmountRefunded,
			&i.AuthorisedAt,
			&i.CapturedAt,
			&i.VoidedAt,
			&i.CreatedAt,
			&i.OrderReference,
			&i.CustomerName,
			&i.OrderStatus,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

