const markVendorPaymentAccountInvalid = `-- name: MarkVendorPaymentAccountInvalid :execrows
UPDATE vendor_payment_accounts
SET status = 'invalid', last_error = $1
WHERE id = $2
  AND status IN ('connecting', 'active')
`

type MarkVendorPaymentAccountInvalidParams struct {
	LastError *string   `json:"last_error"`
	ID        uuid.UUID `json:"id"`
}

// A failed connect, or the provider rejected the key later (revoked).
// Hides card at checkout until the owner reconnects. A disabled account
// stays disabled: it only finishes old payments.
func (q *Queries) MarkVendorPaymentAccountInvalid(ctx context.Context, arg MarkVendorPaymentAccountInvalidParams) (int64, error) {
	result, err := q.db.Exec(ctx, markVendorPaymentAccountInvalid, arg.LastError, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const retireVendorPaymentAccounts = `-- name: RetireVendorPaymentAccounts :execrows
UPDATE vendor_payment_accounts
SET status = 'disabled'
WHERE vendor_id = $1
  AND status IN ('active', 'invalid')
  AND id IS DISTINCT FROM $2::uuid
`

type RetireVendorPaymentAccountsParams struct {
	VendorID uuid.UUID   `json:"vendor_id"`
	KeepID   pgtype.UUID `json:"keep_id"`
}

// Step 5a, same transaction as ActivateVendorPaymentAccount (and the whole
// of DELETE /v1/vendor/payments with keep_id = NULL): the current account
// stops taking new checkouts. Its held payments still finish with its keys.
func (q *Queries) RetireVendorPaymentAccounts(ctx context.Context, arg RetireVendorPaymentAccountsParams) (int64, error) {
	result, err := q.db.Exec(ctx, retireVendorPaymentAccounts, arg.VendorID, arg.KeepID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

