const summariseBranchTakings = `-- name: SummariseBranchTakings :one
SELECT
    count(*)::int AS captured_count,
    coalesce(sum(amount_captured), 0)::bigint AS captured_total,
    coalesce(sum(amount_refunded), 0)::bigint AS refunded_total,
    coalesce(sum(amount_captured - amount_refunded), 0)::bigint AS net_total
FROM payments
WHERE branch_id = $1
  AND captured_at >= $2
  AND captured_at < $3
`

type SummariseBranchTakingsParams struct {
	BranchID     uuid.UUID          `json:"branch_id"`
	CapturedFrom pgtype.Timestamptz `json:"captured_from"`
	CapturedTo   pgtype.Timestamptz `json:"captured_to"`
}

type SummariseBranchTakingsRow struct {
	CapturedCount int32 `json:"captured_count"`
	CapturedTotal int64 `json:"captured_total"`
	RefundedTotal int64 `json:"refunded_total"`
	NetTotal      int64 `json:"net_total"`
}

// Totals for a period by when the money was taken: [captured_from, captured_to).
func (q *Queries) SummariseBranchTakings(ctx context.Context, arg SummariseBranchTakingsParams) (SummariseBranchTakingsRow, error) {
	row := q.db.QueryRow(ctx, summariseBranchTakings, arg.BranchID, arg.CapturedFrom, arg.CapturedTo)
	var i SummariseBranchTakingsRow
	err := row.Scan(
		&i.CapturedCount,
		&i.CapturedTotal,
		&i.RefundedTotal,
		&i.NetTotal,
	)
	return i, err
}
